head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gLdMktTp = js_market;
scwin.pMenuID = $c.stf.InfoMenuID();
//var fr_SecuGrpId = fn_getSecuGrpId(InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.vScrenID = "ULDSTF35003.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2') {
        rdo_SPOT_ISU_TRD_MKT_TP_CD.setDisabled(true);
    } else {
        $c.stf.setObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD, 'A');
    }
    var nowDate = $c.ut.fn_get_nowDate(dts_Date);
    //  기간 from~ to  셋팅	
    edt_SDate.setValue(nowDate);
    edt_EDate.setValue(nowDate);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
};
scwin.fn_list_sync = function() {
    var url = "/listingCommon.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneralForDynamicName" + "&outputMessageId=ATS_SELF_HALT_ISU_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.dscltrend.selfhaltlist" + "&{P}strtDd=" + $c.stf.getObjectValue(edt_SDate) + // 시작일자
        "&{P}endDd=" + $c.stf.getObjectValue(edt_EDate) + // 종료일자
        "&{P}mktTpCd=" + $c.stf.getObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD); // 시장구분

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_getLstRcvDdtm = function() {
    var url = "/AtsContactInfo.do?method=getSelfHaltLstRcvDdtm" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_LstRcv.DataID = encodeURI(url);
    dts_LstRcv.reset();
};
scwin.fn_setLstRcvDdtm = function(sRcvDdtm) {
    $c.stf.setObjectValue(txb_LST_RCV, sRcvDdtm);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
    scwin.fn_getLstRcvDdtm();
};
scwin.img_Excel_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_List, "ATS자체거래정지수신", "", 8, 0);
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_LstRcv_OnLoadCompleted = function(rowcount) {
    scwin.fn_setLstRcvDdtm(dts_LstRcv.getCellData(1, "RCV_DDTM"));
};
scwin.dts_LstRcv_OnLoadError = function() {
    $c.stf.alert_error(dts_LstRcv);
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    if (js_market == "1" || js_market == "2") {
        $c.stf.setObjectValue(rdo_SPOT_ISU_TRD_MKT_TP_CD, js_market);
    }
    scwin.fn_SetCode();
    scwin.fn_list_sync();
    scwin.fn_getLstRcvDdtm();
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar4(edt_SDate, 1);
};
scwin.btn_EDate_onclick = function() {
    popUpCalendar4(edt_EDate, 2);
};
scwin.edt_SDate_OnLastChar = function(ch) {
    afterPopUpCalendar(1); //if(시작일>종료일) 종료일=시작일;

};
scwin.edt_EDate_OnLastChar = function(ch) {
    afterPopUpCalendar(2); //if(시작일>종료일) 시작일=종료일;

};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
